SELECT DISTINCT md.chembl_id AS compound_chembl_id, cs.canonical_smiles FROM compound_structures cs JOIN molecule_dictionary md ON md.molregno = cs.molregno JOIN activities a ON a.molregno = md.molregno JOIN assays ass ON ass.assay_id = a.assay_id JOIN target_dictionary td ON td.tid = ass.tid WHERE td.chembl_id = 'CHEMBL1827' AND ass.assay_organism = 'Homo sapiens' ORDER BY compound_chembl_id, canonical_smiles
